/**
 * Decide a quién se le escribe HOY. Nada más que hoy.
 *
 * A27 quedó reducido a la mitad cuando entró el débito automático: MercadoPago
 * cobra y reintenta solo, así que ya no hay que perseguir a nadie para que
 * renueve. Quedan dos huecos que la pasarela no cubre, y son estos:
 *
 *   1. El cobro rechazado. MercadoPago reintenta hasta 4 veces en 10 días y a
 *      la tercera cuota impaga da de baja la suscripción por su cuenta. Si le
 *      escribimos al instante, la molestamos por algo que se resuelve solo en
 *      dos días; si esperamos los 10, ya la perdimos. Le escribimos a las 48 h.
 *
 *   2. El plan trimestral. Es el único que vence en una fecha: se paga una vez
 *      y da 90 días. Sin aviso, se cae sin que nadie se entere.
 *
 * Lo que este flujo NO hace: sacar a nadie de Skool. Eso sale en el informe de
 * los lunes (A30), que es donde vive todo lo que necesita una mano humana.
 *
 * EL CANDADO. La columna `avisos` de `ventas` guarda qué se le mandó ya a cada
 * una, separado por comas. Sin eso, este flujo corre todos los días y le manda
 * el mismo email todos los días. Es la misma guarda que tiene A4.
 */
const cfg = $('Configuración').first().json;

const MS_DIA = 86400000;
const HOY = new Date();
const HOY_ISO = HOY.toISOString().slice(0, 10);

const TAG_VISTO = 'rechazo-visto';
const TAG_AVISADO = 'rechazo-avisado';
const TAG_PACK_PREVIO = 'pack-previo';
const TAG_PACK_VENCIDO = 'pack-vencido';

/** Fechas de la planilla: vienen como YYYY-MM-DD. Cualquier cosa rara es null. */
function comoFecha(valor) {
  if (!valor) return null;
  const d = new Date(String(valor).slice(0, 10) + 'T00:00:00Z');
  return Number.isNaN(d.getTime()) ? null : d;
}

function diasEntre(desde, hasta) {
  return Math.round((hasta.getTime() - desde.getTime()) / MS_DIA);
}

function primerNombre(valor) {
  const limpio = String(valor ?? '').trim();
  return limpio ? limpio.split(/\s+/)[0] : '';
}

const salidas = [];

for (const item of $input.all()) {
  const fila = item.json ?? {};
  const email = String(fila.email ?? '').trim();
  const referencia = String(fila.external_reference ?? '').trim();

  // Sin email no hay a quién escribirle; sin referencia no hay dónde anotarlo.
  if (!email || !referencia) continue;

  const estado = String(fila.estado ?? '').toLowerCase();
  const plan = String(fila.plan ?? '').toLowerCase();
  const nombre = primerNombre(fila.nombre);
  const hola = nombre ? `Hola ${nombre},` : 'Hola,';

  let avisos = String(fila.avisos ?? '')
    .split(',')
    .map((t) => t.trim())
    .filter(Boolean);

  const tiene = (tag) => avisos.some((t) => t === tag || t.startsWith(tag + ':'));
  const valorDe = (tag) => {
    const encontrado = avisos.find((t) => t.startsWith(tag + ':'));
    return encontrado ? encontrado.slice(tag.length + 1) : null;
  };

  let asunto = null;
  let cuerpo = null;

  // ------------------------------------------------------------------
  // 1. Cobro rechazado
  // ------------------------------------------------------------------
  if (estado === 'cobro_rechazado') {
    // La primera vez que lo vemos sólo dejamos la marca con la fecha. El reloj
    // de las 48 h arranca acá y no en la planilla, porque el webhook no estampa
    // cuándo se rechazó: escribe el estado y nada más.
    const visto = comoFecha(valorDe(TAG_VISTO));

    if (!visto) {
      avisos.push(`${TAG_VISTO}:${HOY_ISO}`);
    } else if (!tiene(TAG_AVISADO) && diasEntre(visto, HOY) * 24 >= Number(cfg.horasParaEscribir)) {
      avisos.push(TAG_AVISADO);
      asunto = 'Se rechazó el cobro de tu suscripción';
      cuerpo = `
        <p>${hola}</p>
        <p>MercadoPago no pudo cobrar tu suscripción al Reto. Suele ser una tarjeta
        vencida o sin límite disponible, y se resuelve en dos minutos.</p>
        <p>Entrá a tu cuenta de MercadoPago, buscá la suscripción y actualizá el medio
        de pago: <a href="${cfg.urlSuscripciones}">${cfg.urlSuscripciones}</a></p>
        <p>Mientras tanto tu acceso sigue abierto. MercadoPago vuelve a intentarlo solo
        durante los próximos días, así que con la tarjeta al día se destraba sin que
        tengas que hacer nada más.</p>
        <p>Si te quedó alguna duda, respondeme este mail.</p>
        <p>Pía</p>
      `;
    }
  } else if (estado === 'pagado' && (tiene(TAG_VISTO) || tiene(TAG_AVISADO))) {
    // El reintento entró. Se limpian las marcas para que el próximo rechazo
    // empiece de cero y no quede tapado por el candado del anterior.
    avisos = avisos.filter((t) => !t.startsWith(TAG_VISTO) && t !== TAG_AVISADO);
  }

  // ------------------------------------------------------------------
  // 2. Vencimiento del plan trimestral
  // ------------------------------------------------------------------
  if (!asunto && plan === 'trimestral' && estado === 'pagado') {
    // acceso_vence es la fuente buena. Si está vacía se deriva de la fecha de
    // la venta: es preferible avisar con un día de corrimiento que no avisar.
    const inicio = comoFecha(fila.fecha);
    let vence = comoFecha(fila.acceso_vence);
    if (!vence && inicio) {
      vence = new Date(inicio.getTime() + Number(cfg.diasDelPack) * MS_DIA);
    }

    if (vence) {
      const restan = diasEntre(HOY, vence);
      const venceTexto = vence.toISOString().slice(0, 10).split('-').reverse().join('/');

      if (restan > 0 && restan <= Number(cfg.diasDeAvisoPrevio) && !tiene(TAG_PACK_PREVIO)) {
        avisos.push(TAG_PACK_PREVIO);
        asunto = `Te quedan ${restan} días de acceso al Reto`;
        cuerpo = `
          <p>${hola}</p>
          <p>Tu plan trimestral vence el ${venceTexto}. Te aviso ahora para que no te
          agarre de sorpresa y puedas decidir con tiempo.</p>
          <p>Si querés seguir, lo renovás desde acá:
          <a href="${cfg.urlComprar}">${cfg.urlComprar}</a></p>
          <p>Y si preferís pasarte a la suscripción mensual, en esa misma página la
          elegís: se cobra sola todos los meses y la cancelás cuando quieras.</p>
          <p>Pía</p>
        `;
      } else if (restan <= 0 && !tiene(TAG_PACK_VENCIDO)) {
        avisos.push(TAG_PACK_VENCIDO);
        asunto = 'Se te venció el acceso al Reto';
        cuerpo = `
          <p>${hola}</p>
          <p>Tu plan trimestral venció el ${venceTexto}. En los próximos días voy a dar
          de baja tu acceso a la comunidad.</p>
          <p>Si querés seguir entrenando, lo renovás acá y no perdés nada de lo que
          avanzaste: <a href="${cfg.urlComprar}">${cfg.urlComprar}</a></p>
          <p>Y si esta etapa se cierra acá, gracias por estos tres meses. Escribime
          cuando quieras volver.</p>
          <p>Pía</p>
        `;
      }
    }
  }

  const avisosNuevo = avisos.join(',');
  const cambio = avisosNuevo !== String(fila.avisos ?? '');

  // Si no hay email para mandar ni marca para mover, la fila no genera trabajo.
  if (!asunto && !cambio) continue;

  salidas.push({
    json: {
      external_reference: referencia,
      avisos: avisosNuevo,
      email,
      nombre: String(fila.nombre ?? '').trim(),
      // mandar=false son las filas que sólo mueven la marca: el rechazo que
      // recién vemos hoy y las limpiezas. No se les escribe.
      mandar: Boolean(asunto),
      asunto: asunto ?? '',
      cuerpo: cuerpo ?? '',
    },
  });
}

return salidas;

