/**
 * Deja pasar sólo las dos columnas que se escriben.
 *
 * El nodo de Google Sheets mapea automáticamente lo que le llega, así que si le
 * pasáramos el item entero aparecerían columnas nuevas en `ventas` llamadas
 * `asunto`, `cuerpo` y `mandar`. Mismo recorte que hace A4 antes de escribir.
 */
return $input.all().map((item) => ({
  json: {
    external_reference: item.json.external_reference,
    avisos: item.json.avisos,
  },
}));
